import{_ as a,o as i,c as n,a0 as o}from"./chunks/framework.DhQjJcnt.js";const p=JSON.parse('{"title":"Skill: /overview","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/overview.md","filePath":"references/skills/overview.md"}'),t={name:"references/skills/overview.md"};function c(l,e,r,h,s,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-overview" tabindex="-1">Skill: <code>/overview</code> <a class="header-anchor" href="#skill-overview" aria-label="Permalink to &quot;Skill: `/overview`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>overview</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/overview</code></li><li>Có thể dùng kèm với <code>common</code>: <code>/overview common</code></li><li>Có thể dùng kèm với cờ khảo cổ mã cũ: <code>/legacy /overview</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Khai thác dữ liệu về mục đích kinh doanh, quy trình chung, và chân dung người dùng (Personas).</li><li>Nếu có cờ <code>/legacy</code>: Đọc file <code>legacy-repos.local.json</code> để mò lại các logic từ dự án mã nguồn cũ.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Các file Markdown lưu tại cấu trúc thư mục: <code>overview/operational-areas/[Tên khu vực nghiệp vụ]/</code>.</li><li>Nếu có modifier <code>/legacy</code>: Tự động thêm tiền tố <code>legacy-</code> vào đầu tên file (ví dụ: <code>overview/legacy-overview.md</code>).</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Nằm ở tầng cao nhất của kiến trúc, xử lý thư mục gốc (Root Folder) <code>overview/</code>.</li><li>Tập trung vào các mảng nghiệp vụ vận hành lớn (Operational Areas) như &quot;Admin operations&quot;, &quot;Workforce operations&quot; thay vì sa đà vào tính năng nhỏ.</li><li><strong>Ranh giới Spec Nghiệp vụ (Business Spec Boundary):</strong> Tài liệu Overview bắt buộc phải là một tài liệu kinh doanh thuần tuý, viết bằng ngôn ngữ của người dùng (User Language).</li><li><strong>CẤM ĐOÁN TỐI KỴ:</strong> Tuyệt đối không nhét các chi tiết kỹ thuật hệ thống (như Database Schemas, cấu hình Cloud, cách định tuyến Routing) vào file Overview. Nếu cần nhắc tới một hệ thống thứ 3, hãy dùng tên thương mại (VD: &quot;Cổng thanh toán Payment Gateway&quot;) thay vì mô tả giao thức API của nó.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Được kích hoạt/điều phối bởi <code>/architecture</code>.</li><li>Nếu cần đi sâu vào kênh giao tiếp (Web/App), dùng <code>/surfaces</code>. Mức nhỏ hơn nữa là <code>/module</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/overview</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const g=a(t,[["render",c]]);export{p as __pageData,g as default};
